import torch
import tilelang as T
import numpy as np

@T.prim_func
def sum_reduce_kernel(
    A: T.Buffer((128, 4096, 4095), "float16"),
    B: T.Buffer((128, 1, 4095), "float16")
):
    # Define the reduction dimension
    reduce_dim = 1

    # Initialize accumulator with zero
    for i in T.serial(128):
        for k in T.serial(4095):
            acc = T.float32(0.0)
            for j in T.serial(4096):
                acc += T.cast(A[i, j, k], "float32")
            B[i, 0, k] = T.cast(acc, "float16")

class ModelNew(torch.nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Create a new tensor with the same shape but reduced dimension
        output_shape = list(x.shape)
        output_shape[self.dim] = 1
        result = torch.empty(output_shape, dtype=torch.float16, device=x.device)

        # Launch the TileLang kernel
        sum_reduce_kernel(x, result)
        return result

